(() => {
  const $ = id => document.getElementById(id);
  const text = (id, value, fallback) => { $(id).textContent = String(value || fallback); };
  const render = state => {
    const p = state.premise || {};
    text('canon-title', p.worldName, 'Unnamed world');
    text('canon-line', (p.location || 'An uncharted place') + ' · ' + (p.era || 'an uncertain age') + ' · ' + (p.tone || 'Unfixed') + ' in tone');
    text('canon-truth', p.truth, 'Its wonder has not been spoken.');
    text('canon-cost', p.cost, 'Its price has not been paid.');
    text('canon-motif', p.motif, 'No texture chosen.');
    const stability = Math.max(1, Math.min(5, Number(p.stability) || 1));
    $('stability-value').textContent = stability + ' / 5';
    $('stability-bar').style.width = (stability * 20) + '%';
    document.querySelectorAll('[data-tone]').forEach(button => {
      const active = button.dataset.tone === p.tone;
      button.classList.toggle('active', active);
      button.setAttribute('aria-pressed', String(active));
    });
    $('sync-text').textContent = 'Canon synced · ' + (p.tone || 'tone open');
  };
  document.querySelectorAll('[data-tone]').forEach(button => button.addEventListener('click', () => window.buildParty.setState('premise.tone', button.dataset.tone)));
  window.buildParty.subscribe(render);
  render(window.buildParty.getState());
})();

(() => {
  const $ = id => document.getElementById(id);
  const color = { Allied: '#70c6d4', Rivals: '#ee7f93', Indebted: '#ddad62', Unknown: '#726c7b' };
  const label = value => String(value || 'Unnamed').toUpperCase().slice(0, 16);
  const render = state => {
    const e = state.entities || {};
    const r = state.relationships || {};
    const names = {
      orra: (e.orra || {}).name || 'Orra Vale',
      choir: (e.choir || {}).name || 'Glass Choir',
      guild: (e.guild || {}).name || 'Ferrymen Guild'
    };
    $('node-orra').textContent = label(names.orra);
    $('node-choir').textContent = label(names.choir);
    $('node-guild').textContent = label(names.guild);
    const rows = [
      ['one', names.orra, names.choir, 'edge-one'],
      ['two', names.orra, names.guild, 'edge-two'],
      ['three', names.guild, names.choir, 'edge-three']
    ];
    rows.forEach(row => {
      const key = row[0], bond = r[key] || {}, nature = bond.nature || 'Unknown';
      const heat = Math.max(1, Math.min(5, Number(bond.heat) || 1));
      $('pair-' + key).textContent = row[1] + ' ↔ ' + row[2];
      $('heat-' + key).textContent = heat + '/5';
      $('summary-' + key).textContent = row[1] + ' and ' + row[2] + ' are ' + nature.toLowerCase() + '; the bond is ' + ['faint','uneasy','binding','dangerous','inescapable'][heat - 1] + '.';
      const edge = $(row[3]);
      edge.style.stroke = color[nature] || color.Unknown;
      edge.style.strokeWidth = String(1 + heat * .65);
      edge.style.strokeDasharray = nature === 'Unknown' ? '7 6' : 'none';
    });
    $('relationship-status').textContent = 'Constellation synced · ' + rows.length + ' active bonds';
  };
  window.buildParty.subscribe(render);
  render(window.buildParty.getState());
})();

(() => {
  const $ = id => document.getElementById(id);
  const banks = {
    titles: ['The Bell Beneath', 'A Map of Ash', 'The Borrowed Constellation', 'Salt for the Sleepless', 'The Last Blue Flame', 'Where Memory Anchors'],
    images: ['a star falls upward from a crowded market', 'a familiar ship returns crewed by strangers', 'every brass compass points toward one child', 'the harbor bells ring from beneath the clouds', 'a forgotten face appears on every city map', 'blue fire spells a name no one admits knowing'],
    complications: ['A trusted guide recognizes the omen and lies about it.', 'The shortest route crosses a memory someone cannot surrender.', 'Three factions offer help, but each demands the same impossible payment.', 'The evidence changes whenever it is described aloud.', 'The supposed victim arranged the entire crisis.', 'An old promise makes the obvious solution forbidden.'],
    choices: ['Save the place and lose the person, or preserve the memory and let the map burn.', 'Tell the city the truth, or protect it with one final lie.', 'Honor the debt, or break the only alliance keeping the sky-roads open.', 'Claim the prize, or return it to the enemy who understands its cost.', 'Wake what sleeps below, or strand everyone above forever.', 'Choose whose version of the past becomes real.']
  };
  const hash = value => {
    let h = 2166136261;
    for (let i = 0; i < value.length; i++) { h ^= value.charCodeAt(i); h = Math.imul(h, 16777619); }
    return h >>> 0;
  };
  const pick = (list, h, offset) => list[(h + offset * 2654435761 >>> 0) % list.length];
  const cleanSeed = value => String(value || '0').replace(/\D/g, '').slice(0, 6) || '0';
  const render = state => {
    const premise = state.premise || {}, recipe = state.recipe || {}, turn = Number(state.turn) || 0;
    const seed = cleanSeed(state.seedNumber);
    const signature = [premise.worldName, premise.cost, recipe.spark, recipe.pressure, recipe.reversal, recipe.shape, seed, turn].join('|');
    const h = hash(signature);
    const title = pick(banks.titles, h, 1);
    const image = pick(banks.images, h, 2);
    const complication = pick(banks.complications, h, 3);
    const choice = pick(banks.choices, h, 4);
    const world = premise.worldName || 'the unnamed world';
    const spark = recipe.spark || 'A disruption';
    const pressure = recipe.pressure || 'before time runs out';
    const reversal = recipe.reversal || 'nothing is what it seems';
    const shape = recipe.shape || 'Story';
    const line = 'In ' + world + ', ' + spark.toLowerCase() + ' forces unlikely allies to act ' + pressure + '—only to learn that ' + reversal + '.';
    $('result-title').textContent = title;
    $('seed-line').textContent = line;
    $('beat-one').textContent = image.charAt(0).toUpperCase() + image.slice(1) + '.';
    $('beat-two').textContent = complication;
    $('beat-three').textContent = choice;
    $('fingerprint').textContent = 'SIGIL ' + h.toString(16).toUpperCase().padStart(8, '0');
    $('turn-count').textContent = String(turn);
    document.querySelector('.dial span').textContent = seed;
    document.querySelector('.dial i').style.transform = 'rotate(' + (h % 360) + 'deg)';
    $('recipe-readout').textContent = shape.toUpperCase() + ' · SEED ' + seed;
    $('assembled-prompt').value = 'Create a ' + shape.toLowerCase() + ' set in ' + world + '.\n\nPREMISE: ' + line + '\nCOST: ' + (premise.cost || 'Define the cost collaboratively.') + '\nINCITING IMAGE: ' + $('beat-one').textContent + '\nCOMPLICATION: ' + complication + '\nFINAL CHOICE: ' + choice + '\n\nKeep the tone atmospheric, make every faction choice consequential, and end on a question the table must answer.';
  };
  $('turn').addEventListener('click', () => {
    const state = window.buildParty.getState();
    window.buildParty.setState('turn', (Number(state.turn) || 0) + 1);
    $('copy-status').textContent = 'Engine advanced.';
  });
  $('copy').addEventListener('click', () => {
    const field = $('assembled-prompt');
    field.focus(); field.select();
    let copied = false;
    try { copied = document.execCommand('copy'); } catch (_) {}
    $('copy-status').textContent = copied ? 'Prompt copied.' : 'Prompt selected—copy it manually.';
  });
  window.buildParty.subscribe(render);
  render(window.buildParty.getState());
})();
